    ('R5-V097', 4, 12665, 'bb5749bef0900afdf4a0dfbabb8808e9', 'auswahl', 'quersumme', 'ac230ae16b2ff7a2c23c594235715662', $rbf${"index": 2}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "Quersumme 20, nicht durch 3 teilbar.", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "Quersumme 10, nicht durch 3 teilbar.", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "3", "text": "Quersumme 17, nicht durch 3 teilbar.", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V098', 4, 12666, '0fe170d81c3d34e84f093c5cd8fe5481', 'zahl', 'quersumme', null, $rbf${"wert": 1}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "22", "text": "die Quersumme selbst als Rest genannt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "7", "text": "den Quotienten der Quersumme genannt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "0", "text": "nur die Endziffer 9 angesehen: Sie ist durch 3 teilbar, also Rest 0", "fehlbild": "fb.bausteine.endziffer_statt_quersumme", "regel": "id.zahlen.bausteine"}]$rbf$::jsonb),
    ('R5-V099', 4, 12667, '09b26145d027a4c5eb960729744fa51d', 'zahl', 'neunerregel', null, $rbf${"wert": 5, "einheit": "Stifte"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "23", "text": "die Quersumme als Rest genannt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "2", "text": "den Quotienten der Quersumme genannt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "4", "text": "mit der Quersumme 22 gerechnet (eine Ziffer falsch addiert)", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V100', 4, 12668, '0c13ffc2d1426e6bfbbf4bf053abe115', 'zahl', 'neunerregel', null, $rbf${"wert": 3, "einheit": "Zahlen"}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "4", "text": "ein Vielfaches zu viel gezählt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "14", "text": "alle Vielfache bis 130 gezählt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "2", "text": "126 vergessen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V101', 4, 12669, 'c7411623a4e7b4cdc3b65ad8bea4a5fa', 'zahl', 'primzahl', null, $rbf${"wert": 17}$rbf$::jsonb, 'id.zahlen.bausteine', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "23", "text": "addiert statt abgezogen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "10", "text": "die Summe 20 halbiert statt 3 abzuziehen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V102', 4, 12670, '2610fb66f6e9b7c1fa4a5c31449fb0dc', 'zahl', 'primzahl', null, $rbf${"wert": 5, "einheit": "Primzahlen"}$rbf$::jsonb, 'id.zahlen.bausteine', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "6", "text": "49 als Primzahl mitgezählt", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "10", "text": "alle ungeraden Zahlen gezählt", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V103', 4, 12671, '1d21e9268d6f39a551166b79fc95d704', 'auswahl', 'primfaktoren', '5670389662f2e8147f1b15ba44208e13', $rbf${"index": 2}$rbf$::jsonb, 'id.zahlen.bausteine', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "Das Ergebnis 5 aus der vorletzten Zeile wurde zusätzlich als Faktor genommen.", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "Jede Primzahl wurde nur einmal genommen, obwohl sie mehrfach als Teiler vorkommt.", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R5-V104', 4, 12672, '2629853b547da11533279bb26e7df80f', 'zahl', 'primfaktoren', null, $rbf${"wert": 42, "einheit": "cm"}$rbf$::jsonb, 'id.zahlen.bausteine', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "6", "text": "nur die gemeinsamen Faktoren 2 und 3 genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "252", "text": "alle Faktoren in der größeren Anzahl genommen (kleinstes gemeinsames Vielfaches)", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "21", "text": "einen Faktor 2 vergessen", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 210
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 106
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 575 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 210)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
